1	/* Unit tests for decoding the 16 B sensor -> hub message (src/ipc_msg.c):
2	 * gt_msg_decode.
3	 *
4	 * Purpose: prove decode reads every field from its documented offset
5	 * (ipc.h), undoes encode exactly, and rejects any message the hub must
6	 * discard (DESIGN.md failure-mode table, Hub: "Length/magic/version check",
7	 * logged as ipc_bad_message) without touching the output. Pure byte
8	 * unpacking: no sockets. Run under make test / asan / memcheck. Implements
9	 * MSD-01 through MSD-07. Encoding is in test_msg_encode.c.
10	 *
11	 * What these tests cannot prove: rejection of a truncated message. recv()
12	 * must return exactly GT_MSG_SIZE bytes; that check arrives with the IPC
13	 * code. */
14	#include <stdint.h>
15	#include <string.h>
16	
17	#include "check.h"
18	#include "ipc.h"
19	
20	/* ---- MSD-01: decode undoes encode ----
21	 * A DATA and a GAP message, at the all-zero and all-max ends of the u32
22	 * fields, come back field for field. */
23	static void test_msd01_round_trip(void)
24	{
25	    const gt_msg originals[] = {
26	        { .type = GT_MSG_DATA, .sensor_id = GT_SENSOR_LIGHT,
27	          .counter = 0, .seq = 0, .value = 0 },
28	        { .type = GT_MSG_GAP, .sensor_id = GT_SENSOR_SOIL,
29	          .counter = UINT32_MAX, .seq = UINT32_MAX, .value = UINT32_MAX },
30	    };
31	    size_t original_count = sizeof originals / sizeof originals[0];
32	
33	    for (size_t message_index = 0; message_index < original_count; message_index++) {
34	        const gt_msg *original = &originals[message_index];
35	        uint8_t wire[GT_MSG_SIZE];
36	        gt_msg decoded;
37	
38	        CHECK_EQ(gt_msg_encode(original, wire), GT_OK);
39	        CHECK_EQ(gt_msg_decode(wire, &decoded), GT_OK);
40	        CHECK_EQ(decoded.type, original->type);
41	        CHECK_EQ(decoded.sensor_id, original->sensor_id);
42	        CHECK_EQ(decoded.counter, original->counter);
43	        CHECK_EQ(decoded.seq, original->seq);
44	        CHECK_EQ(decoded.value, original->value);
45	    }
46	}
47	
48	/* A valid light DATA message written out by hand from the ipc.h layout:
49	 * counter 0x04030201, seq 0x08070605, value 0x0C0B0A09. MSD-03..06 copy
50	 * it and break one byte. */
51	static const uint8_t VALID_WIRE[GT_MSG_SIZE] = {
52	    GT_MSG_MAGIC, GT_MSG_VERSION, GT_MSG_DATA, GT_SENSOR_LIGHT,
53	    0x01, 0x02, 0x03, 0x04,    /* counter, lowest byte first */
54	    0x05, 0x06, 0x07, 0x08,    /* seq */
55	    0x09, 0x0A, 0x0B, 0x0C,    /* value */
56	};
57	
58	/* ---- MSD-02: hand-built bytes decode ----
59	 * Checks decode against the documented layout directly, so a matching bug
60	 * in encode and decode (which MSD-01 alone would miss) still fails. */
61	static void test_msd02_hand_built_bytes(void)
62	{
63	    gt_msg decoded;
64	
65	    CHECK_EQ(gt_msg_decode(VALID_WIRE, &decoded), GT_OK);
66	    CHECK_EQ(decoded.type, GT_MSG_DATA);
67	    CHECK_EQ(decoded.sensor_id, GT_SENSOR_LIGHT);
68	    CHECK_EQ(decoded.counter, 0x04030201u);
69	    CHECK_EQ(decoded.seq, 0x08070605u);
70	    CHECK_EQ(decoded.value, 0x0C0B0A09u);
71	}
72	
73	/* ---- MSD-03: a bad magic byte is rejected ----
74	 * The first sign a stream is out of sync or the sender isn't ours. The
75	 * output is pre-filled with 0x5A and must come back unchanged, so the hub
76	 * can never act on a half-decoded message. */
77	static void test_msd03_bad_magic_rejected(void)
78	{
79	    uint8_t wire[GT_MSG_SIZE];
80	    memcpy(wire, VALID_WIRE, sizeof wire);
81	    wire[0] = 0xA7;   /* the on-disk record's magic: a record is not a message */
82	
83	    gt_msg decoded, untouched;
84	    memset(&decoded, 0x5A, sizeof decoded);
85	    memset(&untouched, 0x5A, sizeof untouched);
86	
87	    CHECK_EQ(gt_msg_decode(wire, &decoded), GT_ERR_CORRUPT);
88	    CHECK(memcmp(&decoded, &untouched, sizeof decoded) == 0);
89	}
90	
91	/* ---- MSD-04: a bad version byte is rejected ----
92	 * A sensor built against a newer layout must not be misread as version 1. */
93	static void test_msd04_bad_version_rejected(void)
94	{
95	    uint8_t wire[GT_MSG_SIZE];
96	    memcpy(wire, VALID_WIRE, sizeof wire);
97	    wire[1] = GT_MSG_VERSION + 1;
98	
99	    gt_msg decoded, untouched;
100	    memset(&decoded, 0x5A, sizeof decoded);
101	    memset(&untouched, 0x5A, sizeof untouched);
102	
103	    CHECK_EQ(gt_msg_decode(wire, &decoded), GT_ERR_CORRUPT);
104	    CHECK(memcmp(&decoded, &untouched, sizeof decoded) == 0);
105	}
106	
107	/* ---- MSD-05: an unknown type is rejected ----
108	 * Types 0 and 3 are neither DATA nor GAP. As DESIGN.md says for the log,
109	 * an unknown type is treated as corrupt. */
110	static void test_msd05_unknown_type_rejected(void)
111	{
112	    const uint8_t unknown_types[] = { 0x00, 0x03 };
113	
114	    for (size_t type_index = 0; type_index < sizeof unknown_types; type_index++) {
115	        uint8_t wire[GT_MSG_SIZE];
116	        memcpy(wire, VALID_WIRE, sizeof wire);
117	        wire[2] = unknown_types[type_index];
118	
119	        gt_msg decoded, untouched;
120	        memset(&decoded, 0x5A, sizeof decoded);
121	        memset(&untouched, 0x5A, sizeof untouched);
122	
123	        CHECK_EQ(gt_msg_decode(wire, &decoded), GT_ERR_CORRUPT);
124	        CHECK(memcmp(&decoded, &untouched, sizeof decoded) == 0);
125	    }
126	}
127	
128	/* ---- MSD-06: a bad sensor_id is rejected ----
129	 * Mirrors MSE-06: 0 (ALL) never comes from one sensor, and 3 is no sensor. */
130	static void test_msd06_bad_sensor_id_rejected(void)
131	{
132	    const uint8_t bad_sensor_ids[] = { GT_SENSOR_ALL, 3 };
133	
134	    for (size_t id_index = 0; id_index < sizeof bad_sensor_ids; id_index++) {
135	        uint8_t wire[GT_MSG_SIZE];
136	        memcpy(wire, VALID_WIRE, sizeof wire);
137	        wire[3] = bad_sensor_ids[id_index];
138	
139	        gt_msg decoded, untouched;
140	        memset(&decoded, 0x5A, sizeof decoded);
141	        memset(&untouched, 0x5A, sizeof untouched);
142	
143	        CHECK_EQ(gt_msg_decode(wire, &decoded), GT_ERR_CORRUPT);
144	        CHECK(memcmp(&decoded, &untouched, sizeof decoded) == 0);
145	    }
146	}
147	
148	/* ---- MSD-07: NULL arguments are rejected ----
149	 * GT_ERR_INVAL (a caller bug), not GT_ERR_CORRUPT (bad bytes). */
150	static void test_msd07_null_args(void)
151	{
152	    gt_msg decoded;
153	
154	    CHECK_EQ(gt_msg_decode(NULL, &decoded), GT_ERR_INVAL);
155	    CHECK_EQ(gt_msg_decode(VALID_WIRE, NULL), GT_ERR_INVAL);
156	}
157	
158	static const test_case_t tests[] = {
159	    {"MSD-01", "decode undoes encode", test_msd01_round_trip},
160	    {"MSD-02", "hand-built bytes decode", test_msd02_hand_built_bytes},
161	    {"MSD-03", "a bad magic byte is rejected", test_msd03_bad_magic_rejected},
162	    {"MSD-04", "a bad version byte is rejected", test_msd04_bad_version_rejected},
163	    {"MSD-05", "an unknown type is rejected", test_msd05_unknown_type_rejected},
164	    {"MSD-06", "a bad sensor_id is rejected", test_msd06_bad_sensor_id_rejected},
165	    {"MSD-07", "NULL arguments are rejected", test_msd07_null_args},
166	};
167	
168	int main(void)
169	{
170	    return RUN_TESTS(tests);
171	}
