1	/* Unit tests for encoding the 16 B sensor -> hub message (src/ipc_msg.c):
2	 * gt_msg_encode.
3	 *
4	 * Purpose: prove every field lands at its documented offset (ipc.h) in
5	 * little-endian byte order, and that a message the hub would reject is
6	 * never put on the wire: bad type, bad sensor_id and NULL arguments fail
7	 * without touching the output. Pure byte packing: no sockets. Run under
8	 * make test / asan / memcheck. Implements MSE-01 through MSE-07. Decoding
9	 * is in test_msg_decode.c.
10	 *
11	 * What these tests cannot prove: that the bytes cross the socket intact.
12	 * That arrives with the IPC client. */
13	#include <stdint.h>
14	#include <string.h>
15	
16	#include "check.h"
17	#include "ipc.h"
18	
19	/* ---- MSE-01: the message is 16 bytes ----
20	 * Pinned because DESIGN.md's buffer sizes and the IPC latency target are
21	 * all stated for a 16 B message. */
22	static void test_mse01_size_is_16(void)
23	{
24	    CHECK_EQ(GT_MSG_SIZE, 16);
25	}
26	
27	/* ---- MSE-02: header bytes 0-3 ----
28	 * magic, version, type, sensor_id, one byte each, in that order. */
29	static void test_mse02_header_bytes(void)
30	{
31	    gt_msg message = { .type = GT_MSG_DATA, .sensor_id = GT_SENSOR_LIGHT,
32	                       .counter = 1, .seq = 0, .value = 300 };
33	    uint8_t wire[GT_MSG_SIZE];
34	
35	    CHECK_EQ(gt_msg_encode(&message, wire), GT_OK);
36	    CHECK_EQ(wire[0], GT_MSG_MAGIC);
37	    CHECK_EQ(wire[1], GT_MSG_VERSION);
38	    CHECK_EQ(wire[2], GT_MSG_DATA);
39	    CHECK_EQ(wire[3], GT_SENSOR_LIGHT);
40	}
41	
42	/* ---- MSE-03: u32 fields are little-endian at 4, 8, 12 ----
43	 * Each value's bytes are all different, so a swapped byte order or a field
44	 * at the wrong offset changes the result. Little-endian = lowest byte
45	 * first: 0x04030201 goes out as 01 02 03 04. */
46	static void test_mse03_u32_fields_little_endian(void)
47	{
48	    gt_msg message = { .type = GT_MSG_DATA, .sensor_id = GT_SENSOR_LIGHT,
49	                       .counter = 0x04030201u, .seq = 0x08070605u, .value = 0x0C0B0A09u };
50	    const uint8_t expected_body[12] = { 0x01, 0x02, 0x03, 0x04,    /* counter */
51	                                        0x05, 0x06, 0x07, 0x08,    /* seq */
52	                                        0x09, 0x0A, 0x0B, 0x0C };  /* value */
53	    uint8_t wire[GT_MSG_SIZE];
54	
55	    CHECK_EQ(gt_msg_encode(&message, wire), GT_OK);
56	    CHECK(memcmp(&wire[4], expected_body, sizeof expected_body) == 0);
57	}
58	
59	/* ---- MSE-04: a GAP message encodes ----
60	 * A sensor whose ring overflowed reports the gap on reconnect: counter =
61	 * first refused reading, value = how many were refused. */
62	static void test_mse04_gap_encodes(void)
63	{
64	    gt_msg gap = { .type = GT_MSG_GAP, .sensor_id = GT_SENSOR_SOIL,
65	                   .counter = 500, .seq = 0, .value = 12 };
66	    uint8_t wire[GT_MSG_SIZE];
67	
68	    CHECK_EQ(gt_msg_encode(&gap, wire), GT_OK);
69	    CHECK_EQ(wire[2], GT_MSG_GAP);
70	    CHECK_EQ(wire[3], GT_SENSOR_SOIL);
71	    CHECK_EQ(wire[12], 12);   /* value's low byte; 12 fits in one byte */
72	}
73	
74	/* ---- MSE-05: an unknown type is rejected ----
75	 * Types 0 and 3 are neither DATA nor GAP: rejected, and the output buffer
76	 * is left exactly as it was (all 0x5A), so no half-written message exists. */
77	static void test_mse05_unknown_type_rejected(void)
78	{
79	    const uint8_t unknown_types[] = { 0x00, 0x03 };
80	    uint8_t untouched[GT_MSG_SIZE];
81	    memset(untouched, 0x5A, sizeof untouched);
82	
83	    for (size_t type_index = 0; type_index < sizeof unknown_types; type_index++) {
84	        gt_msg message = { .type = unknown_types[type_index], .sensor_id = GT_SENSOR_LIGHT,
85	                           .counter = 1, .seq = 0, .value = 300 };
86	        uint8_t wire[GT_MSG_SIZE];
87	        memset(wire, 0x5A, sizeof wire);
88	
89	        CHECK_EQ(gt_msg_encode(&message, wire), GT_ERR_INVAL);
90	        CHECK(memcmp(wire, untouched, sizeof wire) == 0);
91	    }
92	}
93	
94	/* ---- MSE-06: a bad sensor_id is rejected ----
95	 * 0 (GT_SENSOR_ALL) is only meaningful in storage GAP records, never from
96	 * one sensor; 3 is no sensor at all. Output untouched, as in MSE-05. */
97	static void test_mse06_bad_sensor_id_rejected(void)
98	{
99	    const uint8_t bad_sensor_ids[] = { GT_SENSOR_ALL, 3 };
100	    uint8_t untouched[GT_MSG_SIZE];
101	    memset(untouched, 0x5A, sizeof untouched);
102	
103	    for (size_t id_index = 0; id_index < sizeof bad_sensor_ids; id_index++) {
104	        gt_msg message = { .type = GT_MSG_DATA, .sensor_id = bad_sensor_ids[id_index],
105	                           .counter = 1, .seq = 0, .value = 300 };
106	        uint8_t wire[GT_MSG_SIZE];
107	        memset(wire, 0x5A, sizeof wire);
108	
109	        CHECK_EQ(gt_msg_encode(&message, wire), GT_ERR_INVAL);
110	        CHECK(memcmp(wire, untouched, sizeof wire) == 0);
111	    }
112	}
113	
114	/* ---- MSE-07: NULL arguments are rejected ---- */
115	static void test_mse07_null_args(void)
116	{
117	    gt_msg message = { .type = GT_MSG_DATA, .sensor_id = GT_SENSOR_LIGHT,
118	                       .counter = 1, .seq = 0, .value = 300 };
119	    uint8_t wire[GT_MSG_SIZE];
120	
121	    CHECK_EQ(gt_msg_encode(NULL, wire), GT_ERR_INVAL);
122	    CHECK_EQ(gt_msg_encode(&message, NULL), GT_ERR_INVAL);
123	}
124	
125	static const test_case_t tests[] = {
126	    {"MSE-01", "the message is 16 bytes", test_mse01_size_is_16},
127	    {"MSE-02", "header bytes 0-3", test_mse02_header_bytes},
128	    {"MSE-03", "u32 fields are little-endian at 4, 8, 12",
129	     test_mse03_u32_fields_little_endian},
130	    {"MSE-04", "a GAP message encodes", test_mse04_gap_encodes},
131	    {"MSE-05", "an unknown type is rejected", test_mse05_unknown_type_rejected},
132	    {"MSE-06", "a bad sensor_id is rejected", test_mse06_bad_sensor_id_rejected},
133	    {"MSE-07", "NULL arguments are rejected", test_mse07_null_args},
134	};
135	
136	int main(void)
137	{
138	    return RUN_TESTS(tests);
139	}
