    memset(&decoded, 0x5A, sizeof decoded);
    memset(&untouched, 0x5A, sizeof untouched);

    CHECK_EQ(gt_record_decode(wire, &decoded), GT_ERR_CORRUPT);
    CHECK(memcmp(&decoded, &untouched, sizeof decoded) == 0);
