1	/* 16 B sensor -> hub message encode/decode (see ipc.h for the layout).
2	 *
3	 * Purpose: turns a gt_msg into the exact bytes sent over hub.sock and back.
4	 * Fields are written one byte at a time in little-endian order instead of
5	 * copying the struct, because the compiler may add padding between struct
6	 * fields and the Pi and a test machine need not agree on it. Decode is the
7	 * hub's first check (DESIGN.md failure-mode table, Hub: "Length/magic/
8	 * version check"): anything it rejects is logged as ipc_bad_message.
9	 *
10	 * Pure byte packing: no sockets. The client that sends these bytes goes in
11	 * src/ipc_client.c. */
12	#include "ipc.h"
13	
14	#include <stddef.h>
15	
16	/* Write `value` into out[0..3], lowest byte first. */
17	static void put_u32_le(uint8_t *out, uint32_t value)
18	{
19	    out[0] = (uint8_t)(value);
20	    out[1] = (uint8_t)(value >> 8);
21	    out[2] = (uint8_t)(value >> 16);
22	    out[3] = (uint8_t)(value >> 24);
23	}
24	
25	/* Read in[0..3], lowest byte first. Each byte is widened to uint32_t
26	 * before shifting, so a shift by 24 can't overflow an int. */
27	static uint32_t get_u32_le(const uint8_t *in)
28	{
29	    return (uint32_t)in[0]
30	         | ((uint32_t)in[1] << 8)
31	         | ((uint32_t)in[2] << 16)
32	         | ((uint32_t)in[3] << 24);
33	}
34	
35	/* Whether type and sensor_id are allowed on the sensor -> hub hop: DATA or
36	 * GAP, from the light or soil sensor. GT_SENSOR_ALL is only for storage GAP
37	 * records, never from one sensor. Shared so encode refuses exactly what
38	 * decode would reject. */
39	static int fields_valid(uint8_t type, uint8_t sensor_id)
40	{
41	    int type_ok = type == GT_MSG_DATA || type == GT_MSG_GAP;
42	    int sensor_ok = sensor_id == GT_SENSOR_LIGHT || sensor_id == GT_SENSOR_SOIL;
43	    return type_ok && sensor_ok;
44	}
45	
46	/* Pack `message` into the 16 wire bytes in `out`. Everything is checked
47	 * before the first byte is written, so a rejected message leaves `out`
48	 * exactly as it was. GT_ERR_INVAL on NULL args or a bad type/sensor_id. */
49	gt_status gt_msg_encode(const gt_msg *message, uint8_t out[GT_MSG_SIZE])
50	{
51	    if (message == NULL || out == NULL) {
52	        return GT_ERR_INVAL;
53	    }
54	    if (!fields_valid(message->type, message->sensor_id)) {
55	        return GT_ERR_INVAL;
56	    }
57	
58	    out[0] = GT_MSG_MAGIC;
59	    out[1] = GT_MSG_VERSION;
60	    out[2] = message->type;
61	    out[3] = message->sensor_id;
62	    put_u32_le(&out[4], message->counter);
63	    put_u32_le(&out[8], message->seq);
64	    put_u32_le(&out[12], message->value);
65	    return GT_OK;
66	}
67	
68	/* Unpack 16 wire bytes from `in` into `message`. The header is checked
69	 * first and `message` is written only once every check has passed, so the
70	 * hub never sees a half-decoded message. GT_ERR_INVAL on NULL args (a
71	 * caller bug); GT_ERR_CORRUPT on bad magic, version, type or sensor_id
72	 * (bad bytes: the hub drops the connection so the sensor resyncs). */
73	gt_status gt_msg_decode(const uint8_t in[GT_MSG_SIZE], gt_msg *message)
74	{
75	    if (in == NULL || message == NULL) {
76	        return GT_ERR_INVAL;
77	    }
78	    if (in[0] != GT_MSG_MAGIC || in[1] != GT_MSG_VERSION || !fields_valid(in[2], in[3])) {
79	        return GT_ERR_CORRUPT;
80	    }
81	
82	    message->type = in[2];
83	    message->sensor_id = in[3];
84	    message->counter = get_u32_le(&in[4]);
85	    message->seq = get_u32_le(&in[8]);
86	    message->value = get_u32_le(&in[12]);
87	    return GT_OK;
88	}
